            }
        }
        let left_depth = node
            .borrow()
            .left_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        let right_depth = node
            .borrow()
            .right_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        if (left_depth as i32 - right_depth as i32).abs() > 1 {
