fn rotate_right(&mut self, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l = {
        let pb = p.borrow();
        pb.left_child_node.as_ref().unwrap().clone()
    };

    // Get info before mutations
    let p_parent_weak = p.borrow().parent_node.clone();
    let (c2, c2_count) = {
        let lb = l.borrow();
        (lb.right_child_node.clone(), lb.right_child_count)
    };

    // Update P's parent to point to L
    match &p_parent_weak {
        Some(pw) => {
            if let Some(parent) = pw.upgrade() {
                let is_left = {
                    let pb = parent.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
                };
                if is_left {
                    parent.borrow_mut().left_child_node = Some(l.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(l.clone());
                }
            }
        }
        None => {
            self.root_node = Some(l.clone());
        }
    }

    // Set L's parent to P's old parent
    l.borrow_mut().parent_node = p_parent_weak;

    // Set P's left child to c2
    p.borrow_mut().left_child_node = c2.clone();
    p.borrow_mut().left_child_count = c2_count;

    // If c2 exists, set its parent to P
    if let Some(ref c2r) = c2 {
        c2r.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Update P's depth
    {
        let pb = p.borrow();
        let ld = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let rd = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        drop(pb);
        p.borrow_mut().depth = if ld > rd { ld } else { rd };
    }

    // Set P's parent to L, and L's right child to P
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));
    l.borrow_mut().right_child_node = Some(p.clone());

    // Update L's right_child_count
    {
        let pb = p.borrow();
        l.borrow_mut().right_child_count = pb.left_child_count + pb.right_child_count + 1;
    }

    // Update L's depth
    {
        let lb = l.borrow();
        let ld = lb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let rd = lb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        drop(lb);
        l.borrow_mut().depth = if ld > rd { ld } else { rd };
    }

    l.clone()
}
