    let has_left = node.borrow().left_child_node.is_some();
    let has_right = node.borrow().right_child_node.is_some();

    let mut bubble_up: Option<Rc<RefCell<BOSNode>>> = None;

    if has_left && has_right {
        // Two children case
        let (left_depth, right_depth) = {
            let nb = node.borrow();
            let ld = nb.left_child_node.as_ref().unwrap().borrow().depth;
            let rd = nb.right_child_node.as_ref().unwrap().borrow().depth;
            (ld, rd)
        };

        // Find candidate
        let (candidate, lost_child, bubble_start) = if left_depth >= right_depth {
            // Go left, find rightmost
            node.borrow_mut().left_child_count -= 1;
            let mut candidate = node.borrow().left_child_node.as_ref().unwrap().clone();

            while candidate.borrow().right_child_node.is_some() {
                candidate.borrow_mut().right_child_count -= 1;
                let next = candidate.borrow().right_child_node.as_ref().unwrap().clone();
                candidate = next;
            }

            let lost_child = candidate.borrow().left_child_node.clone();
            let bubble_start = {
                let cb = candidate.borrow();
                cb.parent_node.as_ref().and_then(|w| w.upgrade()).unwrap()
            };

            // Replace candidate with lost_child in bubble_start
            {
                let mut bb = bubble_start.borrow_mut();
                if bb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                    bb.left_child_node = lost_child.clone();
                } else {
                    bb.right_child_node = lost_child.clone();
                }
            }

            if let Some(ref lc) = lost_child {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
            }

            (candidate, lost_child, bubble_start)
        } else {
            // Go right, find leftmost
            node.borrow_mut().right_child_count -= 1;
            let mut candidate = node.borrow().right_child_node.as_ref().unwrap().clone();

            while candidate.borrow().left_child_node.is_some() {
                candidate.borrow_mut().left_child_count -= 1;
                let next = candidate.borrow().left_child_node.as_ref().unwrap().clone();
                candidate = next;
            }

            let lost_child = candidate.borrow().right_child_node.clone();
            let bubble_start = {
                let cb = candidate.borrow();
                cb.parent_node.as_ref().and_then(|w| w.upgrade()).unwrap()
            };

            {
                let mut bb = bubble_start.borrow_mut();
                if bb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                    bb.left_child_node = lost_child.clone();
                } else {
                    bb.right_child_node = lost_child.clone();
                }
            }

            if let Some(ref lc) = lost_child {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
            }

            (candidate, lost_child, bubble_start)
        };

        // Place candidate at node's position
        let node_parent_weak = node.borrow().parent_node.clone();
        {
            if let Some(ref pw) = node_parent_weak {
                if let Some(parent) = pw.upgrade() {
                    let is_left = {
                        let pb = parent.borrow();
                        pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                    };
                    if is_left {
                        parent.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        parent.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
        }

        // Set candidate's parent and children
        {
            let nb = node.borrow();
            let mut cb = candidate.borrow_mut();
            cb.parent_node = nb.parent_node.clone();
            cb.left_child_node = nb.left_child_node.clone();
            cb.left_child_count = nb.left_child_count;
            cb.right_child_node = nb.right_child_node.clone();
            cb.right_child_count = nb.right_child_count;
        }

        // Update children's parent pointers to candidate
        if let Some(ref left) = candidate.borrow().left_child_node {
            left.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
        }
        if let Some(ref right) = candidate.borrow().right_child_node {
            right.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
        }

