fn bostree_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let left_depth = node_depth(&node.borrow().left_child_node);
    let right_depth = node_depth(&node.borrow().right_child_node);
    right_depth as i32 - left_depth as i32
}

fn recompute_depth(node: &Rc<RefCell<BOSNode>>) {
    let ld = node_depth(&node.borrow().left_child_node);
    let rd = node_depth(&node.borrow().right_child_node);
    node.borrow_mut().depth = imax(ld, rd);
}

fn rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l = p.borrow().left_child_node.as_ref().unwrap().clone();

    // Update P's parent to point to L
    let p_parent = p.borrow().parent_node.clone();
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let par = parent.borrow();
                par.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, p)).unwrap_or(false)
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(l.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(l.clone());
            }
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    l.borrow_mut().parent_node = p_parent;

    // P's left becomes L's right
    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;
    p.borrow_mut().left_child_node = l_right.clone();
    p.borrow_mut().left_child_count = l_right_count;

    if let Some(ref lc) = p.borrow().left_child_node {
        lc.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    recompute_depth(p);
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));
    l.borrow_mut().right_child_node = Some(p.clone());

    let p_lc = p.borrow().left_child_count;
    let p_rc = p.borrow().right_child_count;
    l.borrow_mut().right_child_count = p_lc + p_rc + 1;

    recompute_depth(&l);
    l
}

fn rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let r = p.borrow().right_child_node.as_ref().unwrap().clone();

    let p_parent = p.borrow().parent_node.clone();
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let par = parent.borrow();
                par.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, p)).unwrap_or(false)
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(r.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(r.clone());
            }
        }
    } else {
        tree.root_node = Some(r.clone());
    }

    r.borrow_mut().parent_node = p_parent;

    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;
    p.borrow_mut().right_child_node = r_left.clone();
    p.borrow_mut().right_child_count = r_left_count;

    if let Some(ref rc) = p.borrow().right_child_node {
        rc.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    recompute_depth(p);
    p.borrow_mut().parent_node = Some(Rc::downgrade(&r));
    r.borrow_mut().left_child_node = Some(p.clone());

    let p_lc = p.borrow().left_child_count;
    let p_rc = p.borrow().right_child_count;
    r.borrow_mut().left_child_count = p_lc + p_rc + 1;

    recompute_depth(&r);
    r
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        match &self.root_node {
            Some(root) => {
                let r = root.borrow();
                r.left_child_count + r.right_child_count + 1
            }
            None => 0,
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Find insertion point
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;
        let mut went_left = true;

        let mut current = self.root_node.clone();
        while let Some(node) = current {
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                went_left = true;
                current = node.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count += 1;
                went_left = false;
                current = node.borrow().right_child_node.clone();
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        if let Some(ref parent) = parent_node {
            if went_left {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }
        } else {
            self.root_node = Some(new_node.clone());
            return new_node;
        }

        // Check if depth changed
        let depth_changed = {
            let p = parent_node.as_ref().unwrap().borrow();
            (p.left_child_node.is_some()) != (p.right_child_node.is_some())
        };

        if depth_changed {
            parent_node.as_ref().unwrap().borrow_mut().depth += 1;
            let mut bubble = parent_node.as_ref().unwrap().borrow().parent_node.clone();

            loop {
                let parent = match bubble {
                    Some(ref pw) => match pw.upgrade() {
                        Some(p) => p,
                        None => break,
                    },
                    None => break,
                };

                let new_left_depth = node_depth(&parent.borrow().left_child_node);
                let new_right_depth = node_depth(&parent.borrow().right_child_node);
                let max_depth = imax(new_left_depth, new_right_depth);

                {
                    let mut pm = parent.borrow_mut();
                    if pm.depth != max_depth {
                        pm.depth = max_depth;
                    } else {
                        break;
                    }
                }

                if new_left_depth == new_right_depth + 2 {
                    let left_child = parent.borrow().left_child_node.as_ref().unwrap().clone();
                    if bostree_balance(&left_child) > 0 {
                        rotate_left(self, &left_child);
                    }
                    let rotated = rotate_right(self, &parent);
                    bubble = rotated.borrow().parent_node.clone();
                } else if new_right_depth == new_left_depth + 2 {
                    let right_child = parent.borrow().right_child_node.as_ref().unwrap().clone();
                    if bostree_balance(&right_child) < 0 {
                        rotate_right(self, &right_child);
                    }
                    let rotated = rotate_left(self, &parent);
                    bubble = rotated.borrow().parent_node.clone();
                } else {
                    bubble = parent.borrow().parent_node.clone();
                }
            }
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();
        let mut bubble_up: Option<Rc<RefCell<BOSNode>>> = None;

        if has_left && has_right {
            // Two children: find replacement candidate
            let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
            let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

            let candidate: Rc<RefCell<BOSNode>>;
            let bubble_start: Rc<RefCell<BOSNode>>;

            if left_depth >= right_depth {
                // In-order predecessor (rightmost of left subtree)
                node.borrow_mut().left_child_count -= 1;
                let mut cand = node.borrow().left_child_node.as_ref().unwrap().clone();
                while cand.borrow().right_child_node.is_some() {
                    cand.borrow_mut().right_child_count -= 1;
                    let next = cand.borrow().right_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                let lost_child = cand.borrow().left_child_node.clone();
                bubble_start = cand.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap_or_else(|| node.clone());

                {
                    let bs = bubble_start.borrow();
                    let is_left = bs.left_child_node.as_ref()
                        .map(|n| Rc::ptr_eq(n, &cand)).unwrap_or(false);
                    drop(bs);
                    if is_left {
                        bubble_start.borrow_mut().left_child_node = lost_child.clone();
                    } else {
                        bubble_start.borrow_mut().right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
                }
                candidate = cand;
            } else {
                // In-order successor (leftmost of right subtree)
                node.borrow_mut().right_child_count -= 1;
                let mut cand = node.borrow().right_child_node.as_ref().unwrap().clone();
                while cand.borrow().left_child_node.is_some() {
                    cand.borrow_mut().left_child_count -= 1;
                    let next = cand.borrow().left_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                let lost_child = cand.borrow().right_child_node.clone();
                bubble_start = cand.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap_or_else(|| node.clone());

                {
                    let bs = bubble_start.borrow();
                    let is_left = bs.left_child_node.as_ref()
                        .map(|n| Rc::ptr_eq(n, &cand)).unwrap_or(false);
                    drop(bs);
                    if is_left {
                        bubble_start.borrow_mut().left_child_node = lost_child.clone();
                    } else {
                        bubble_start.borrow_mut().right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
                }
                candidate = cand;
            }

            // Anchor candidate into node's position
            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref pw) = node_parent {
                if let Some(parent) = pw.upgrade() {
                    let is_left = {
                        let p = parent.borrow();
                        p.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, node)).unwrap_or(false)
                    };
                    if is_left {
                        parent.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        parent.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }

            candidate.borrow_mut().parent_node = node_parent;

            // Transfer children from node to candidate
            let node_left = node.borrow().left_child_node.clone();
            let node_left_count = node.borrow().left_child_count;
            let node_right = node.borrow().right_child_node.clone();
            let node_right_count = node.borrow().right_child_count;

            candidate.borrow_mut().left_child_node = node_left.clone();
            candidate.borrow_mut().left_child_count = node_left_count;
            candidate.borrow_mut().right_child_node = node_right.clone();
            candidate.borrow_mut().right_child_count = node_right_count;

            if let Some(ref lc) = node_left {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref rc) = node_right {
                rc.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            // Rebalance from bubble_start up to (but not including) candidate
            if !Rc::ptr_eq(&bubble_start, node) {
                let mut bs = Some(bubble_start.clone());
                loop {
                    let cur = match bs {
                        Some(ref c) => c.clone(),
                        None => break,
                    };
                    if Rc::ptr_eq(&cur, &candidate) {
                        break;
                    }
                    recompute_depth(&cur);
                    let balance = bostree_balance(&cur);
                    if balance > 1 {
                        let right_child = cur.borrow().right_child_node.as_ref().unwrap().clone();
                        if bostree_balance(&right_child) < 0 {
                            rotate_right(self, &right_child);
                        }
                        let rotated = rotate_left(self, &cur);
                        bs = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else if balance < -1 {
                        let left_child = cur.borrow().left_child_node.as_ref().unwrap().clone();
                        if bostree_balance(&left_child) > 0 {
                            rotate_left(self, &left_child);
                        }
                        let rotated = rotate_right(self, &cur);
                        bs = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else {
                        bs = cur.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    }
                }
            }

            recompute_depth(&candidate);

            bubble_up = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref bu) = bubble_up {
                let is_left = {
                    let b = bu.borrow();
                    b.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, &candidate)).unwrap_or(false)
                };
                if is_left {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            // Zero or one child
            let child = if has_left {
                node.borrow().left_child_node.clone()
            } else {
                node.borrow().right_child_node.clone()
            };
            let child_count = if has_left {
                node.borrow().left_child_count
            } else {
                node.borrow().right_child_count
            };

            let node_parent = node.borrow().parent_node.clone();
            if node_parent.is_none() {
                self.root_node = child.clone();
                if let Some(ref c) = child {
                    c.borrow_mut().parent_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.as_ref().unwrap().upgrade().unwrap();
                let is_left = {
                    let p = parent.borrow();
                    p.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, node)).unwrap_or(false)
                };
                if is_left {
                    parent.borrow_mut().left_child_node = child.clone();
                    parent.borrow_mut().left_child_count = child_count;
                } else {
                    parent.borrow_mut().right_child_node = child.clone();
                    parent.borrow_mut().right_child_count = child_count;
                }
                if let Some(ref c) = child {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }
                bubble_up = Some(parent);
            }
        }

        // Rebalance up to root
        let mut bubbling_finished = false;
        loop {
            let bu = match bubble_up {
                Some(ref b) => b.clone(),
                None => break,
            };

            if !bubbling_finished {
                let left_depth = node_depth(&bu.borrow().left_child_node);
                let right_depth = node_depth(&bu.borrow().right_child_node);
                let new_depth = imax(left_depth, right_depth);
                let depth_changed = bu.borrow().depth != new_depth;
                bu.borrow_mut().depth = new_depth;

                let balance = bostree_balance(&bu);
                if balance < -1 {
                    let left_child = bu.borrow().left_child_node.as_ref().unwrap().clone();
                    if bostree_balance(&left_child) > 0 {
                        rotate_left(self, &left_child);
                    }
                    let rotated = rotate_right(self, &bu);
                    bubble_up = Some(rotated);
                } else if balance > 1 {
                    let right_child = bu.borrow().right_child_node.as_ref().unwrap().clone();
                    if bostree_balance(&right_child) < 0 {
                        rotate_right(self, &right_child);
                    }
                    let rotated = rotate_left(self, &bu);
                    bubble_up = Some(rotated);
                } else if !depth_changed {
                    bubbling_finished = true;
                }
            }

            // Fix child counts going up
            let bu_parent = bu.borrow().parent_node.clone();
            if let Some(ref pw) = bu_parent {
                if let Some(gp) = pw.upgrade() {
                    let is_left = {
                        let g = gp.borrow();
                        g.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, &bu)).unwrap_or(false)
                    };
                    if is_left {
                        gp.borrow_mut().left_child_count -= 1;
                    } else {
                        gp.borrow_mut().right_child_count -= 1;
                    }
                    bubble_up = Some(gp);
                    continue;
                }
            }
            bubble_up = None;
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        node.borrow_mut().weak_ref_count -= 1;
        if node.borrow().weak_ref_count == 0 {
            if let Some(free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else if node.borrow().weak_ref_node_valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        loop {
            let node = match current {
                Some(ref n) => n.clone(),
                None => return None,
            };
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node);
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        loop {
            let node = match current {
                Some(ref n) => n.clone(),
                None => return None,
            };
            let left_count = node.borrow().left_child_count;
            if left_count <= idx {
                idx -= left_count;
                if idx == 0 {
                    return Some(node);
                }
                idx -= 1;
                current = node.borrow().right_child_node.clone();
            } else {
                current = node.borrow().left_child_node.clone();
            }
        }
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        fn print_helper(node: &Rc<RefCell<BOSNode>>) {
            let n = node.borrow();
            println!("  {} [label=\"\\N ({},{},{})\"];", n.key, n.left_child_count, n.right_child_count, n.depth);
            if let Some(ref pw) = n.parent_node {
                if let Some(parent) = pw.upgrade() {
                    println!("  {} -> {} [color=green];", n.key, parent.borrow().key);
                }
            }
            if let Some(ref left) = n.left_child_node {
                println!("  {} -> {}", n.key, left.borrow().key);
                print_helper(left);
            }
            if let Some(ref right) = n.right_child_node {
                println!("  {} -> {}", n.key, right.borrow().key);
                print_helper(right);
            }
        }
        if let Some(ref root) = self.root_node {
            println!("digraph {{\n  ordering = out;");
            print_helper(root);
            println!("}}");
        }
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    assert!(node.borrow().weak_ref_count < 127);
    assert!(node.borrow().weak_ref_count > 0);
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref right) = node.borrow().right_child_node {
        let mut current = right.clone();
        loop {
            let next = current.borrow().left_child_node.clone();
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent_weak = current.borrow().parent_node.clone();
            match parent_weak {
                Some(ref pw) => {
                    if let Some(parent) = pw.upgrade() {
                        let is_right = {
                            let p = parent.borrow();
                            p.right_child_node.as_ref().map(|n| Rc::ptr_eq(n, &current)).unwrap_or(false)
                        };
                        if is_right {
                            current = parent;
                        } else {
                            return Some(parent);
                        }
                    } else {
                        return None;
                    }
                }
                None => return None,
            }
        }
    } else {
        None
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref left) = node.borrow().left_child_node {
        let mut current = left.clone();
        loop {
            let next = current.borrow().right_child_node.clone();
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent_weak = current.borrow().parent_node.clone();
            match parent_weak {
                Some(ref pw) => {
                    if let Some(parent) = pw.upgrade() {
                        let is_left = {
                            let p = parent.borrow();
                            p.left_child_node.as_ref().map(|n| Rc::ptr_eq(n, &current)).unwrap_or(false)
                        };
                        if is_left {
                            current = parent;
                        } else {
                            return Some(parent);
                        }
                    } else {
                        return None;
                    }
                }
                None => return None,
            }
        }
    } else {
        None
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = Some(node.clone());
    loop {
        let n = match current {
            Some(ref c) => c.clone(),
            None => break,
        };
        let parent_weak = n.borrow().parent_node.clone();
        match parent_weak {
            Some(ref pw) => {
                if let Some(parent) = pw.upgrade() {
                    let is_right = {
                        let p = parent.borrow();
                        p.right_child_node.as_ref().map(|rn| Rc::ptr_eq(rn, &n)).unwrap_or(false)
                    };
                    if is_right {
                        counter += 1 + parent.borrow().left_child_count;
                    }
                    current = Some(parent);
                } else {
                    break;
                }
            }
            None => break,
        }
    }
    counter
}
